    vector<int> products, prices;
public:
    Cashier(int n, int discount, vector<int>& products, vector<int>& prices)
        : n(n), discount(discount), products(products), prices(prices) {}

    double getBill(vector<int>& product, vector<int>& amount) {
        ++count;
        long long total = 0;
        for (int i = 0; i < (int)product.size(); ++i) {
            int idx = find(this->products.begin(), this->products.end(), product[i]) - this->products.begin();
            total += (long long)prices[idx] * amount[i];
        }
        if (count % n == 0) return total * (100 - discount) / 100.0;
        return (double)total;
    }
};

